import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"Error catalog — every failure message, by subsystem","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/error-catalog.md","filePath":"troubleshooting/error-catalog.md"}'),c={name:"troubleshooting/error-catalog.md"};function i(l,e,r,s,n,h){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="error-catalog-—-every-failure-message-by-subsystem" tabindex="-1">Error catalog — every failure message, by subsystem <a class="header-anchor" href="#error-catalog-—-every-failure-message-by-subsystem" aria-label="Permalink to &quot;Error catalog — every failure message, by subsystem&quot;">​</a></h1><p>This is the full-repo failure-message inventory: the strings you actually see, organized by component and file, each with <strong>trigger → investigation → fix</strong>. ~1700 distinct error-semantic strings exist in the tree; repeated templates are merged here with a file list, so this page is the complete map, not a sample. Numeric codes are in <a href="./error-codes.html">error-codes.md</a>; failures that print <em>nothing</em> are in <a href="./silent-failures.html">silent-failures.md</a>.</p><p>Investigation commands are spelled for the <code>ush&gt;</code> prompt. The general ladder for anything: <code>health</code> → <code>dmesg 100</code> → the family&#39;s status command → the family&#39;s <code>_test</code> stub (<a href="./../manual/hidden-commands.html">../manual/hidden-commands.md</a>).</p><hr><h2 id="_1-ocbl-—-the-boot-loader-5-classes" tabindex="-1">1. OCBL — the boot loader (5 classes) <a class="header-anchor" href="#_1-ocbl-—-the-boot-loader-5-classes" aria-label="Permalink to &quot;1. OCBL — the boot loader (5 classes)&quot;">​</a></h2><h3 id="_1-1-bios-payload-path-ocbl-common-ocbl-main-c" tabindex="-1">1.1 BIOS payload path (<code>ocbl/common/ocbl_main.c</code>) <a class="header-anchor" href="#_1-1-bios-payload-path-ocbl-common-ocbl-main-c" aria-label="Permalink to &quot;1.1 BIOS payload path (`ocbl/common/ocbl_main.c`)&quot;">​</a></h3><ul><li><code>[boot] FATAL: payload volume remount failed</code> — the /boot remount before kernel load failed. Investigate: boot the ISO&#39;s other entry; capture serial (<code>-serial file:</code>). Fix: re-run <code>install &lt;dev&gt;</code> or <code>grub-install &lt;dev&gt;</code> from a working boot.</li><li><code>[boot] VBE FAILED (kernel will refuse)</code> — no VBE mode; OCOS requires a framebuffer. Fix: enable the VGA/VBE device (QEMU: default VGA; real hardware: BIOS video settings).</li><li><code>[boot] FATAL: kernel load failed</code> — ELF load of <code>/boot/opencube.elf</code> failed (missing/corrupt). Fix: re-install, or boot slot B / the ISO and repair the volume.</li><li><code>[boot] ACPI S5 shutdown</code> / <code>[boot] S5 did not power off; halting</code> — menu shutdown path; the second line means the board ignores S5. Use the physical/host power control.</li></ul><h3 id="_1-2-uefi-flavor-ocbl-efi-efi-entry-c-helpers" tabindex="-1">1.2 UEFI flavor (<code>ocbl/efi/efi_entry.c</code> + helpers) <a class="header-anchor" href="#_1-2-uefi-flavor-ocbl-efi-efi-entry-c-helpers" aria-label="Permalink to &quot;1.2 UEFI flavor (`ocbl/efi/efi_entry.c` + helpers)&quot;">​</a></h3><ul><li><code>[efi] FATAL: fixed low-memory windows not ...</code> — the 0x98000/0x9B000 OCST islands are occupied by firmware. Fix: firmware setup option to free low memory, or boot the BIOS flavor.</li><li><code>[boot] FATAL: chainload volume remount failed</code> (payload variant too) — target ESP unreadable. Fix: verify the ESP on another machine.</li><li><code>[boot] GOP FAILED (kernel will refuse)</code> — UEFI GOP gave no mode. Fix: firmware video settings; OVMF defaults work.</li><li><code>[boot] FATAL: kernel load failed</code> — as §1.1.</li><li><code>[efi] FATAL: memory map failed</code> / <code>[efi] GetMemoryMap failed: 0x&lt;hex&gt;</code> — EFI memory services refused. Retry; firmware bug class.</li><li><code>[efi] EBS retry (0x&lt;hex&gt;)</code> / <code>[boot] FATAL: ExitBootServices refused</code> — ExitBootServices retried then fatal: a boot driver still holds a stale map key. Update firmware / use BIOS flavor.</li><li>Chainload helpers: <code>[boot] FATAL: chainload buffer alloc failed</code>, <code>chainload target not readable: &lt;path&gt;</code>, <code>[boot] LoadImage failed: 0x&lt;hex&gt;</code> — the foreign loader is missing/not PE. Expected for the non-PE stub test disk; fix the target ESP.</li><li><code>[boot] GOP: SetMode failed, keeping current</code> — benign; the current mode is used.</li></ul><h3 id="_1-3-chainload-ocbl-bios-ocbl-chain-c" tabindex="-1">1.3 Chainload (<code>ocbl/bios/ocbl_chain.c</code>) <a class="header-anchor" href="#_1-3-chainload-ocbl-bios-ocbl-chain-c" aria-label="Permalink to &quot;1.3 Chainload (`ocbl/bios/ocbl_chain.c`)&quot;">​</a></h3><ul><li><code>[chain] VBR read failed</code> — the chosen volume&#39;s boot record is unreadable. Fix: the volume is not actually bootable; pick another entry.</li></ul><h3 id="_1-4-the-boot-failure-judge-ocbl-common-ocbl-statemon-c" tabindex="-1">1.4 The boot-failure judge (<code>ocbl/common/ocbl_statemon.c</code>) <a class="header-anchor" href="#_1-4-the-boot-failure-judge-ocbl-common-ocbl-statemon-c" aria-label="Permalink to &quot;1.4 The boot-failure judge (`ocbl/common/ocbl_statemon.c`)&quot;">​</a></h3><ul><li>Screen: <code>Open Cube OS failed to boot at stage: &lt;STAGE&gt;</code> + <code>Rebooting to recovery...</code> — OCBL judged ≥ 8 s of RTC silence against the stage budget (30 s boot / 10 s per phase). The next boot auto-routes to OCIRE <strong>one-shot</strong>.</li><li>Serial: <code>[state] previous boot judged FAILED at stage &lt;STAGE_NAME&gt; (silence &lt;n&gt;s) - BOOT_FAILED recorded</code>.</li><li>Honest non-failures (informational): <code>previous boot shut down cleanly (seq &lt;n&gt;)</code>, <code>warm reset with recent progress (silence &lt;n&gt;s) - not a failure</code>, <code>previous boot armed no payload - no failure</code>.</li><li><code>[state] BOOT_FAILED record pending (stall &lt;n&gt;s) - detection degrades to the next reset</code> — no hardware watchdog to enforce the budget; the judgment lands on the next reset instead.</li><li><code>[state] USER_REQUEST recorded - recovery session</code> — you picked OCIRE in the menu.</li><li><code>[rtc] clock frozen - skipping the dwell</code> — RTC not ticking; silence cannot be measured. Fix: RTC battery / <code>rtc</code> after boot.</li><li><code> (the kernel will halt after the stage)</code> — the /HANGAT diagnostic is armed; see <a href="./boot-failures.html">boot-failures.md</a>.</li></ul><h3 id="_1-5-scan-menu-labels-ocbl-common-ocbl-scan-c" tabindex="-1">1.5 Scan/menu labels (<code>ocbl/common/ocbl_scan.c</code>) <a class="header-anchor" href="#_1-5-scan-menu-labels-ocbl-common-ocbl-scan-c" aria-label="Permalink to &quot;1.5 Scan/menu labels (`ocbl/common/ocbl_scan.c`)&quot;">​</a></h3><p>Not errors, but the visible outcome of scanning: <code>Open Cube OS (slot B|A, &lt;size&gt; KiB)</code> (+ <code> rollback</code> when <code>next_B</code>+<code>bootfail_B</code> force slot A), <code>OpenCubeOS Setup (OCSE)</code>, <code>OCIRE recovery</code>, <code>EFI loader</code>, <code>&lt;volume&gt; (cd|hd&lt;N&gt; gpt|p&lt;N&gt;)</code>. Serial trace: <code>[scan] entries: &lt;N&gt;</code>. A missing entry means the marker file was not found — see <a href="./boot-failures.html">boot-failures.md</a> §scanner.</p><h2 id="_2-ocire-—-the-recovery-kernel-5-classes" tabindex="-1">2. OCIRE — the recovery kernel (5 classes) <a class="header-anchor" href="#_2-ocire-—-the-recovery-kernel-5-classes" aria-label="Permalink to &quot;2. OCIRE — the recovery kernel (5 classes)&quot;">​</a></h2><h3 id="_2-1-the-supervisor-ocire-bootsvc-c" tabindex="-1">2.1 The supervisor (<code>ocire_bootsvc.c</code>) <a class="header-anchor" href="#_2-1-the-supervisor-ocire-bootsvc-c" aria-label="Permalink to &quot;2.1 The supervisor (`ocire_bootsvc.c`)&quot;">​</a></h3><ul><li><code>Reset failed on this machine; halting.</code> — 8042/CF9 reset both ineffective. Use host power control.</li><li><code>Supervisor: no OCIRE recovery volume found </code> — the hd1 0xEE+FAT12 volume is absent. Fix: re-install with the recovery partition (OCSE installer creates it).</li><li><code>Supervisor: recovery volume malformed (mailbox/log missing). Entering the full shell.</code> — the shadow volume exists but its mailbox is bad. Run <code>syscheck</code>, then <code>repair quick</code> from the full shell.</li><li><code>Supervisor: mailbox write failed - skipping the reboot to avoid a reset loop; entering the full ...</code> — the anti-reset-loop guard (BUG-47 fix). The mailbox is unreliable; repair it before rebooting.</li><li><code>WARNING: log agent digest mismatch</code> + <code>The agent will NOT be injected (tamper guard).</code> — the agent image does not match the mailbox digest. Treat as tampering or corruption: <code>syscheck</code>, <code>repair</code>.</li><li><code>Supervisor: /BOOT/OPENCUBE.ELF not found on the ...</code> / <code>OCOS kernel too large (&lt;n&gt; ...)</code> — the kexec source is missing/oversized. Fix: <code>syscheck</code> then <code>repair</code> rebuilds the system volume from the golden set.</li><li><code>Supervisor: FATAL - cannot write the mailbox. </code> — the embed channel is dead; recovery routing degrades. <code>repair</code>.</li><li><code>Watchdog arm FAILED - continuing without it </code> — 6300ESB absent; recovery proceeds without a hardware leash.</li><li><code>Supervisor: kexec refused the image (rc &lt;n&gt;)</code> — the OCOS ELF failed validation. <code>syscheck</code>.</li></ul><h3 id="_2-2-syscheck-repair-ocire-recover-c" tabindex="-1">2.2 syscheck / repair (<code>ocire_recover.c</code>) <a class="header-anchor" href="#_2-2-syscheck-repair-ocire-recover-c" aria-label="Permalink to &quot;2.2 syscheck / repair (`ocire_recover.c`)&quot;">​</a></h3><p>Volume verification verdicts (checks 1-10): <code>FAIL</code>, <code>BAD (magic/state invalid)</code>, <code>BAD (magic/cursor invalid)</code>, <code>MISMATCH (agent image vs mailbox digest)</code>, <code>FAIL (cannot parse)</code>, <code>... MISSING/UNREADABLE</code>, <code>... DIGEST MISMATCH</code>, <code>I/O ERROR</code>, <code>4-10. skipped (volumes incomplete)</code>, <code>8-10. skipped (no manifest)</code> — each names a broken piece; <code>repair</code> is the response to all of them.</p><ul><li><code>logread: recovery volume not found (run syscheck).</code> / <code>logread: cannot read /LOG/BOOT.LOG.</code> / <code>logread: BAD ring header (magic/cursor) - use &#39;repair quick&#39; to reset it.</code> — the boot-log channel; <code>repair quick</code> resets the ring.</li><li>Repair flow failures: <code>REBUILD FAILED</code>, <code>RESET FAILED</code>, <code>FAILED - aborting (volume left as-is).</code>, <code>failed (re-run or use another golden set)</code>, <code>cannot verify files. Aborting.</code> — re-run repair; if it repeats, the golden set itself is damaged.</li><li><code>WARNING: this REFORMATS the OpenCubeOS system volume; all data on it will be lost. Type YES to continue:</code> — the deliberate destructive confirm; type <code>YES</code> exactly.</li></ul><h3 id="_2-3-stall-explanations-ocire-ocbl-c" tabindex="-1">2.3 Stall explanations (<code>ocire_ocbl.c</code>) <a class="header-anchor" href="#_2-3-stall-explanations-ocire-ocbl-c" aria-label="Permalink to &quot;2.3 Stall explanations (`ocire_ocbl.c`)&quot;">​</a></h3><p><code>The kernel failed to start or stalled in its earliest ...</code> (3 stage variants, each ending <code>retry the boot.</code>), <code>The default L1 application (ush) failed to come up. Run syscheck to verify the system image, then retry ...</code>, <code>Unknown stall point. Run syscheck ...</code> — these are the user-facing mapping of the OCBL judgment; follow the embedded advice. Boot-record echo lines (<code>Recovery session requested by the user (seq &lt;n&gt;)</code>, <code>No boot failure was judged - this is a manual recovery session.</code>, <code>Previous boot FAILED at stage &lt;STAGE&gt;</code>) state why you are in recovery.</p><h3 id="_2-4-exceptions-ocire-idt-c" tabindex="-1">2.4 Exceptions (<code>ocire_idt.c</code>) <a class="header-anchor" href="#_2-4-exceptions-ocire-idt-c" aria-label="Permalink to &quot;2.4 Exceptions (`ocire_idt.c`)&quot;">​</a></h3><p><code>&lt;vec #XX name&gt;</code> + <code> error 0x&lt;hex&gt;</code> + <code>System halted.</code> — an unhandled fault inside OCIRE itself (7 vector names: #DE/#OF/#UD/#TS/#GP/#CP, fallback <code>unknown vector</code>). Capture serial; this is a bug class.</p><h3 id="_2-5-shell-boot-honesty-ocire-shell-c-ocire-main-c" tabindex="-1">2.5 Shell / boot honesty (<code>ocire_shell.c</code>, <code>ocire_main.c</code>) <a class="header-anchor" href="#_2-5-shell-boot-honesty-ocire-shell-c-ocire-main-c" aria-label="Permalink to &quot;2.5 Shell / boot honesty (`ocire_shell.c`, `ocire_main.c`)&quot;">​</a></h3><ul><li><code>Unknown command: &lt;cmd&gt;</code> — the recovery shell is tiny; <code>help</code> lists it.</li><li><code>Power off not supported on this machine; halting.</code> / <code>Reset failed on this machine; halting.</code> — platform limits.</li><li><code>ACPI: not found - legacy power ports will be used</code> — honest degradation, not an error.</li><li><code>=== ocire-agent: klog snapshot refused ===</code> — the guard-only klog op refused a non-guard caller; expected when probing the channel.</li></ul><h2 id="_3-ocse-—-the-installer-environment-6-classes" tabindex="-1">3. OCSE — the installer environment (6 classes) <a class="header-anchor" href="#_3-ocse-—-the-installer-environment-6-classes" aria-label="Permalink to &quot;3. OCSE — the installer environment (6 classes)&quot;">​</a></h2><h3 id="_3-1-stage-failures-ocse-kernel-main-c-ocse-main-c" tabindex="-1">3.1 Stage failures (<code>ocse/kernel/main.c</code>, <code>ocse_main.c</code>) <a class="header-anchor" href="#_3-1-stage-failures-ocse-kernel-main-c-ocse-main-c" aria-label="Permalink to &quot;3.1 Stage failures (`ocse/kernel/main.c`, `ocse_main.c`)&quot;">​</a></h3><ul><li><code>[ocse] STAGE &lt;n&gt; FAILED: &lt;what&gt;</code> — a boot stage of the installer kernel failed (serial + VGA + boot log). Read <code>&lt;what&gt;</code>; the mirrored kernel messages are in §5/§6 below.</li><li><code>[ocse] FATAL: no usable disk - halting</code> — no install target.</li><li><code>... B, ocblmbr.bin MISSING</code> / <code>[ocse] medium check: ocos.tar MISSING</code> — the install medium is incomplete (bad burn/download). Re-download the ISO; verify size/SHA.</li><li><code>direct rendering (alloc failed)</code> — installer GUI could not allocate its framebuffer.</li></ul><h3 id="_3-2-ocsecl-—-the-command-line-ocse-cl-c" tabindex="-1">3.2 ocsecl — the command line (<code>ocse_cl.c</code>) <a class="header-anchor" href="#_3-2-ocsecl-—-the-command-line-ocse-cl-c" aria-label="Permalink to &quot;3.2 ocsecl — the command line (`ocse_cl.c`)&quot;">​</a></h3><p>Navigation/files: <code>ls: bad path</code>, <code>cd: bad path</code>, <code>cat: cannot open </code>, <code>write: cannot create </code>, <code>touch: cannot create </code>, <code>mkdir: cannot create (exists, or parent missing)</code>, <code>rmdir: cannot remove (not found, not a directory, or not empty)</code>, <code>rm: cannot remove </code>, <code>cp: bad source name</code>, <code>cp: destination path too long</code>, <code>cp: copy failed (err &lt;n&gt;)</code>, <code>mv: moving a directory across parents is not supported</code> — standard path/argument errors; <code>ls</code>/<code>pwd</code> the target first. Partitions: <code>mkpart: bad start</code> / <code>bad end</code>, <code>rmpart: bad partition number</code>, <code>setflag: bad partition number</code>, <code>install: bad partition number</code> — numeric guards. <code>rmpart: WARNING: deleting a partition DESTROYS ITS DATA!</code> and <code>: WARNING: formatting DESTROYS ALL DATA on the target device!</code> are the destructive confirms. tar/dd/sha: <code>tar: cannot open </code>, <code>tar: out of memory</code>, <code>tar: archive error (&lt;n&gt;)</code>, <code>dd: cannot open input: &lt;d&gt;</code>, <code>dd: I/O error (&lt;n&gt;)</code>, <code>sha256sum: read error</code>, <code>sha256sum: bad sector count</code> — medium or memory problems. Misc: <code>&#39; - unknown command (try &#39;help&#39;)</code>, <code>click: bad coordinate</code>.</p><h3 id="_3-3-wizard-dictionary-ocse-i18n-c" tabindex="-1">3.3 Wizard dictionary (<code>ocse_i18n.c</code>) <a class="header-anchor" href="#_3-3-wizard-dictionary-ocse-i18n-c" aria-label="Permalink to &quot;3.3 Wizard dictionary (`ocse_i18n.c`)&quot;">​</a></h3><p><code>disk not found: </code>, <code>partition not found</code>, <code>invalid range (need start &lt; end &lt;= disk size)</code>, <code>format failed</code>, <code>... failed (busy or not a mount point)</code>, <code>install: FATAL - install medium incomplete (OCOS.TAR / OCBLMBR.BIN)</code>, <code>config: invalid key or value</code>, <code>A command failed:</code> — the GUI wizard&#39;s failure texts (EN/zh pairs); each maps to the ocsecl step named after it.</p><h3 id="_3-4-the-installer-ocse-inst-c-—-the-step-chain" tabindex="-1">3.4 The installer (<code>ocse_inst.c</code>) — the step chain <a class="header-anchor" href="#_3-4-the-installer-ocse-inst-c-—-the-step-chain" aria-label="Permalink to &quot;3.4 The installer (`ocse_inst.c`) — the step chain&quot;">​</a></h3><p><code>ocbl-install: cannot open &lt;f&gt;</code>, <code>ocbl-install: stage1 verify FAILED</code>, <code>ocbl-install: core verify FAILED</code>, <code>install: recovery partition skipped - </code>, <code>recovery kernel unreadable</code>, <code>mkpart failed</code>, <code>created partition not found</code>, <code>partition device missing</code>, <code>mkfs.fat32 failed</code>, <code>mount failed</code>, <code>cannot create /boot/ocire.elf on it</code>, <code>recovery kernel short read</code>, <code>install: FATAL - no such partition: &lt;p&gt;</code>, <code>install: FATAL - extraction failed</code>, <code>install: FATAL - /boot/opencube.elf missing after extraction</code>, <code>install: FATAL - ocbl-install failed</code>, <code>install: FATAL - could not set the boot flag</code>, <code>config: cannot write the configuration</code> — the chain is sequential; the FIRST message names the broken step. Almost all reduce to: bad target disk (run the disk checks first) or bad medium (§3.1&#39;s MISSING class).</p><h3 id="_3-5-input-guards-ocse-wizard-c" tabindex="-1">3.5 Input guards (<code>ocse_wizard.c</code>) <a class="header-anchor" href="#_3-5-input-guards-ocse-wizard-c" aria-label="Permalink to &quot;3.5 Input guards (`ocse_wizard.c`)&quot;">​</a></h3><p><code>[wizard] refuse: existing ...</code>, <code>mount (too long)</code>, <code>install (too long)</code>, <code>write /mnt/etc/users (record too long)</code>, <code>The user record (name + full name) is too long for the ...</code> — length guards; shorten the input.</p><h3 id="_3-6-mkfs-the-mirrored-pool-ocse-mkfs-c" tabindex="-1">3.6 mkfs + the mirrored pool (<code>ocse_mkfs.c</code>) <a class="header-anchor" href="#_3-6-mkfs-the-mirrored-pool-ocse-mkfs-c" aria-label="Permalink to &quot;3.6 mkfs + the mirrored pool (`ocse_mkfs.c`)&quot;">​</a></h3><p><code>: device name too long</code> — mkfs argument guard. The rest of OCSE&#39;s driver/fs/kernel error files mirror the OCOS strings in §5/§6 byte-for-byte (same gzip/tar/config enums, same fs/driver messages) — one shared pool; dedupe on the string, not the file.</p><h2 id="_4-ocos-kernel-7-classes" tabindex="-1">4. OCOS kernel (7 classes) <a class="header-anchor" href="#_4-ocos-kernel-7-classes" aria-label="Permalink to &quot;4. OCOS kernel (7 classes)&quot;">​</a></h2><h3 id="_4-1-boot-fatals-and-stage-fails-core-boot-main-c" tabindex="-1">4.1 Boot FATALs and stage FAILs (<code>core_boot_main.c</code>) <a class="header-anchor" href="#_4-1-boot-fatals-and-stage-fails-core-boot-main-c" aria-label="Permalink to &quot;4.1 Boot FATALs and stage FAILs (`core_boot_main.c`)&quot;">​</a></h3><p>Hard failures (halt):</p><ul><li><code>[oc] FATAL: bad multiboot2 magic</code> — not booted via OCBL/GRUB mb2. Fix: boot through the ISO&#39;s OCBL menu.</li><li><code>[oc] FATAL: multiboot2 parse failed</code> — mbi tag walk hit an invalid tag. Capture serial; loader bug class.</li><li><code>[oc] FATAL: fb_init failed</code> — no GOP/VBE mode passed. Fix the bootloader&#39;s video handoff.</li></ul><p>Stage FAIL verdicts (<code>[HH:MM:SS.mmm] &lt;stage&gt;: FAIL</code>):</p><ul><li><code>WP-01 extension self-test</code> — one of the 4 L1-extension canaries failed. Kernel surface regression; report.</li><li><code>exception self-test</code> — #UD/#PF/#BP self-test counters wrong. Report.</li><li><code>ACPI: RSDP not found (no ACPI power paths)</code> — no RSDP; power features degrade to legacy ports.</li><li><code>CMOS RTC: probe inconclusive (VRT not set)</code> — RTC battery absent (VMs always); <code>date</code> falls back to ms-since-boot.</li><li><code>HPET: no usable ACPI HPET table</code> / <code>ACPI PM timer: no usable PM_TMR_BLK</code> — timer sources degrade; TSC/PIT carry on.</li><li><code>kmalloc/kfree self-test</code> — heap round-trip failed. Report.</li></ul><h3 id="_4-2-l1-launch-core-boot-l1launch-c" tabindex="-1">4.2 L1 launch (<code>core_boot_l1launch.c</code>) <a class="header-anchor" href="#_4-2-l1-launch-core-boot-l1launch-c" aria-label="Permalink to &quot;4.2 L1 launch (`core_boot_l1launch.c`)&quot;">​</a></h3><ul><li><code>l1 launcher: no default L1 app declared; entering recovery shell</code> — build damage (registry empty). Report.</li><li><code>l1 launcher: failed to start the default L1 app; entering recovery shell</code> — ush failed to start. Boot the ISO, run <code>help_a_test</code>.</li><li><code>l1 launcher: default L1 app exited; L0 halting (reboot or use the boot menu)</code> — ush returned (end of session; normal after <code>shutdown</code>).</li></ul><h3 id="_4-3-ocst-state-area-core-boot-state-c" tabindex="-1">4.3 OCST state area (<code>core_boot_state.c</code>) <a class="header-anchor" href="#_4-3-ocst-state-area-core-boot-state-c" aria-label="Permalink to &quot;4.3 OCST state area (`core_boot_state.c`)&quot;">​</a></h3><ul><li><code>absent - stage recording only, no hardware reset </code> — no 6300ESB watchdog: boot-failure detection degrades to next-reset judgment.</li><li><code>[ocst] /HANGAT diagnostic: will halt after stage </code> / <code>[ocst] HANGAT: deliberate halt with interrupts off </code> / <code>[ocst] HANGAT runtime: deliberate halt with </code> — the /HANGAT file is present! Delete <code>/HANGAT</code> from the payload volume (see <a href="./boot-failures.html">boot-failures.md</a>).</li><li><code>[ocst] L1 ISOLATION FAILURE: a user page covers 0x&lt;hex&gt;</code> — a user PTE maps the supervisor-only OCST mailbox window. Security check tripped; report immediately.</li></ul><h3 id="_4-4-elf-loader-static-path-core-usermode-c" tabindex="-1">4.4 ELF loader, static path (<code>core_usermode.c</code>) <a class="header-anchor" href="#_4-4-elf-loader-static-path-core-usermode-c" aria-label="Permalink to &quot;4.4 ELF loader, static path (`core_usermode.c`)&quot;">​</a></h3><ul><li><code>[user] no address space</code> — PMM/VMM exhausted at process create. <code>mem</code>, <code>free</code>; stop memory-hungry jobs.</li><li><code>[user] not an ELF file</code> / <code>[user] not ELF64</code> — the exec target is not a valid ELF64. Expected for <code>badapp</code>-class fixtures.</li><li><code>user: process table full (max &lt;N&gt; processes)</code> — too many concurrent processes. <code>ps</code>, <code>kill &lt;pid&gt;</code> stragglers.</li></ul><h3 id="_4-5-dynamic-exec-core-usermode-c-dynlink-prefix" tabindex="-1">4.5 Dynamic exec (<code>core_usermode.c</code>, <code>dynlink:</code> prefix) <a class="header-anchor" href="#_4-5-dynamic-exec-core-usermode-c-dynlink-prefix" aria-label="Permalink to &quot;4.5 Dynamic exec (`core_usermode.c`, `dynlink:` prefix)&quot;">​</a></h3><p><code>PT_INTERP: (offset out of bounds)</code>, <code>dynlink: PT_INTERP not present</code>, <code>dynlink: no embedded ld.so for path</code>, <code>dynlink: ld.so too small</code> / <code>not an ELF file</code> / <code>not ELF64</code> / <code>has no PT_LOAD segment</code>, <code>dynlink: main image failed ELF header checks</code>, <code>dynlink: main PT_LOAD out of user window</code>, <code>dynlink: failed to map main PT_LOAD</code>, the <code>libfoo</code> twins — the dynamic chain is broken; almost always a build or registry-integrity issue. Verify with <code>ldd &lt;program&gt;</code>; re-run <code>l1test</code>.</p><h3 id="_4-6-program-header-validation-both-paths" tabindex="-1">4.6 Program-header validation (both paths) <a class="header-anchor" href="#_4-6-program-header-validation-both-paths" aria-label="Permalink to &quot;4.6 Program-header validation (both paths)&quot;">​</a></h3><p><code>[user] bad phentsize</code>, <code>[user] program-header table out of bounds</code>, <code>[user] PT_LOAD file range out of bounds</code>, <code>[user] PT_LOAD vaddr+memsz overflow</code>, <code>[user] PT_LOAD memsz &lt; filesz</code>, <code>[user] PT_LOAD vaddr in kernel space</code>, <code>[user] PT_LOAD segments overlap</code> — the ELF being loaded is malformed/hostile. If it is a shipped program, report; if it is your own, fix the link script.</p><h3 id="_4-7-scheduler-config-core-sched-c-core-lib-config-c" tabindex="-1">4.7 Scheduler + config (<code>core_sched.c</code>, <code>core_lib_config.c</code>) <a class="header-anchor" href="#_4-7-scheduler-config-core-sched-c-core-lib-config-c" aria-label="Permalink to &quot;4.7 Scheduler + config (`core_sched.c`, `core_lib_config.c`)&quot;">​</a></h3><ul><li><code>PANIC: idle task stack allocation failed - halting</code> — sched-init OOM. Increase RAM (512 MiB comfortable).</li><li>klog WARN <code>kthread %s: guard page unmap FAILED at 0x%lx (stack protection absent)</code> — 2 MiB huge-page split failed; the task runs without stack-overflow protection (a known P1, tracked on GitHub Issues). Harmless but report-worthy.</li><li><code>config: backend bring-up FAILED</code> — /etc could not be mounted; config degrades to ramfs (changes lost on reboot). See <a href="./storage-issues.html">storage-issues.md</a>.</li><li><code>config: invalid auto_check value - using no (safe default)</code> / <code>config: invalid online_update value - using yes (default)</code> — the config file has junk values; defaults applied. Fix with <code>config set</code>.</li></ul><h2 id="_5-ocos-services-21-classes-by-family" tabindex="-1">5. OCOS services (21 classes, by family) <a class="header-anchor" href="#_5-ocos-services-21-classes-by-family" aria-label="Permalink to &quot;5. OCOS services (21 classes, by family)&quot;">​</a></h2><h3 id="_5-1-audio" tabindex="-1">5.1 audio <a class="header-anchor" href="#_5-1-audio" aria-label="Permalink to &quot;5.1 audio&quot;">​</a></h3><ul><li><code>play: out of memory</code> / <code>play: device error</code> — allocation or device failure. <code>sound</code> lists devices; <code>mem</code> checks memory.</li><li><code>: unknown device &#39;&lt;name&gt;</code> — <code>play -d</code>/<code>volume</code> target not registered. Use a name from <code>sound</code>.</li><li><code>[audio_rw_test] kmalloc(48000) failed =&gt; FAIL</code> — OOM during the loopback test.</li><li><code>[audio_rw_test] no sound cards registered =&gt; SKIPPED</code> — honest skip; attach an audio device (QEMU <code>-device intel-hda</code>).</li><li><code>driver rejected the rate</code> / <code>(unsupported, correctly rejected) =&gt; PASS</code> — negative fixtures: illegal rates are SUPPOSED to be refused.</li><li>QEMU-10 <code>hda</code> model dead-loops on 44.1 kHz — known model limitation; real hardware programs it fine.</li></ul><h3 id="_5-2-block-—-cache-device-protection" tabindex="-1">5.2 block — cache + device protection <a class="header-anchor" href="#_5-2-block-—-cache-device-protection" aria-label="Permalink to &quot;5.2 block — cache + device protection&quot;">​</a></h3><ul><li><code>blkcache: alloc FAILED - cache disabled (raw I/O)</code> — the 64-slot LRU write-back cache could not allocate; the system continues uncached (slower). <code>mem</code>; report if persistent.</li><li><code>blk: refusing device &#39;&lt;name&gt;</code> — registering a device with invalid geometry. Driver-level; report.</li><li><code>blk: write to protected device &lt;name&gt; REFUSED (ocire recovery disk)</code> / <code>blk: cached write to protected device REFUSED (ocire recovery disk)</code> — the whole-disk OCIRE protection is armed; writes to the recovery volume are blocked <strong>by design</strong>. Use OCIRE&#39;s own <code>repair</code> to modify that volume.</li></ul><h3 id="_5-3-block-—-parted-mkfs-fsck-commands" tabindex="-1">5.3 block — parted/mkfs/fsck commands <a class="header-anchor" href="#_5-3-block-—-parted-mkfs-fsck-commands" aria-label="Permalink to &quot;5.3 block — parted/mkfs/fsck commands&quot;">​</a></h3><ul><li><code>parted: device not found</code> / <code>: device name too long</code> — wrong device string. <code>lsblk</code> first.</li><li><code>mkfs.fat32: device not found</code> / <code>mkfs.fat32: device too small</code> / the exfat variants (<code>device too small (need at least 65 sectors, got &lt;N&gt;)</code>, <code>device too small for FAT + heap</code>) / <code>mkfs.ext4: device not found</code> — target checks. Pick a real, big enough device from <code>lsblk</code>.</li><li><code>WARNING: formatting DESTROYS ALL DATA on the target device!</code> — the confirm; bare <code>y</code> proceeds.</li><li>fsck (FAT32 only): <code>fsck: cannot read boot sector</code>, <code>fsck: invalid boot signature (not 0x55AA)</code>, <code>fsck: not a FAT32 volume (fsck supports FAT32 only; got invalid BPB)</code>, <code>fsck: unsupported bytes_per_sector (fsck reads raw 512-byte sectors; got &lt;N&gt;)</code>, <code>fsck: out of memory</code>, <code>fsck: FAIL (&lt;detail&gt;)</code>, <code>fsck: FAIL (cluster count mismatch: counted &lt;A&gt; ...</code> — the volume is not a readable FAT32. <code>fatstat &lt;dev&gt;</code> shows the parsed BPB; reformat if the data is expendable.</li></ul><h3 id="_5-4-block-—-install-abdisk-grub-install-chains" tabindex="-1">5.4 block — install/abdisk/grub-install chains <a class="header-anchor" href="#_5-4-block-—-install-abdisk-grub-install-chains" aria-label="Permalink to &quot;5.4 block — install/abdisk/grub-install chains&quot;">​</a></h3><ul><li><code>grub-install: MBR gap too small for &lt;N&gt;</code> — the post-MBR gap cannot host core.img. Repartition with a ≥ 1 MiB gap (modern layout) or use GPT.</li><li><code>grub-install: failed to write boot sector</code> / <code>failed to write core.img</code> — write failure; check the medium.</li><li>abdisk chain: <code>abdisk: device not found</code>, <code>device too small (need &lt;N&gt;)</code>, <code>WARNING - all data on &lt;dev&gt;</code>, <code>failed to write partition table</code>, <code>failed to register partition</code>, <code>mkfs.fat32 failed on p&lt;N&gt;</code>, <code>mount p1 failed</code>, <code>failed to write grub.cfg</code>, <code>mount p2 failed</code>, <code>failed to write slot A kernel</code>, <code>grub-install failed</code> — sequential; the first failure is the real one. Bad disk or too-small target covers most cases.</li><li>install chain: <code>install: device not found</code>, <code>device too small (need &gt;= 64 MiB ...)</code>, <code>disk too large for MBR (&gt;2TiB) or too small</code>, <code>failed to write partition table</code>, <code>failed to register p1</code>, <code>mkfs.fat32 failed</code>, <code>mount p1 failed</code>, <code>failed to write /boot/opencube.elf</code>, <code>failed to write grub.cfg</code>, <code>grub-install failed</code> — same reading rule.</li><li><code>(build system error)</code> — an embedded asset is missing from the build. Rebuild.</li></ul><h3 id="_5-5-camera-uvc-ir-parallel-gameport-scsi" tabindex="-1">5.5 camera (UVC/IR/parallel/gameport/SCSI) <a class="header-anchor" href="#_5-5-camera-uvc-ir-parallel-gameport-scsi" aria-label="Permalink to &quot;5.5 camera (UVC/IR/parallel/gameport/SCSI)&quot;">​</a></h3><ul><li><code>nec corrupted rejected</code>, <code>mjpeg truncated rejected</code>, <code>set format unknown rejected</code>, <code>set frame mismatch rejected</code>, <code>capture refused before start</code> — negative fixtures; these PASSing is correct behavior.</li><li><code>no parallel port present - skipping live steps</code>, <code>no stick (timeout)</code>, <code>&lt;N&gt; failures - PASS|FAIL</code> — honest hardware-absence reporting.</li></ul><h3 id="_5-6-crash" tabindex="-1">5.6 crash <a class="header-anchor" href="#_5-6-crash" aria-label="Permalink to &quot;5.6 crash&quot;">​</a></h3><ul><li><code>crashlog: flush FAILED (no filesystem mounted?)</code> — no VFS mount to write /var/log. Mount a volume, re-run <code>crashlog</code>.</li><li>Panic-time <code>crash log: ... FAILED (no filesystem)</code> — the panic itself happened before/without a filesystem; the serial console carries the record.</li></ul><h3 id="_5-7-crypto" tabindex="-1">5.7 crypto <a class="header-anchor" href="#_5-7-crypto" aria-label="Permalink to &quot;5.7 crypto&quot;">​</a></h3><ul><li>Self-test verdicts <code>SHA-256: FAIL</code>, <code>AES-128: FAIL</code>, <code>HMAC-SHA256: FAIL</code>, <code>HMAC-SHA384: FAIL</code> — crypto primitives broken: build/toolchain issue; report.</li><li><code>DIFFERENT (memory corruption!)</code> — heap canary check; report immediately.</li><li><code>RSA modulus too small</code>, <code>pss: bad DB padding at %d: %02x</code> — RSA-PSS padding out of spec (hostile or broken peer).</li><li>X509 verify strings: <code>bad certificate format</code>, <code>unsupported algorithm</code>, <code>signature verification failed</code>, <code>hostname mismatch</code>, <code>issuer certificate missing</code>, <code>unknown error</code> — see X509_E_* in <a href="./error-codes.html">error-codes.md</a>.</li></ul><h3 id="_5-8-diag-the-self-test-console-121-strings-—-the-highlights" tabindex="-1">5.8 diag (the self-test console, 121 strings — the highlights) <a class="header-anchor" href="#_5-8-diag-the-self-test-console-121-strings-—-the-highlights" aria-label="Permalink to &quot;5.8 diag (the self-test console, 121 strings — the highlights)&quot;">​</a></h3><ul><li><code>usage: crashtest panic|exc|pf|assert|wd|ovf|dump|policy [halt|reboot]</code> — the grammar; see <a href="./../manual/hidden-commands.html">../manual/hidden-commands.md</a>.</li><li><code>crashtest: #UD returned unexpectedly</code> / <code>unmapped write returned unexpectedly</code> / <code>assert returned unexpectedly</code> — the injected fault SURVIVED, which is itself a failure. Report.</li><li><code>crashtest: dump FAILED (no boot-time buffer)</code> — the boot-time dump buffer was not allocated (memory-constrained boot).</li><li>nice guards: <code>nice: tid too large</code>, <code>nice: invalid tid</code>, <code>nice: priority out of range (0..31)</code>, <code>nice: invalid tid or prio (0..31)</code>, <code>nice: invalid tid (not in use)</code> — remember it is a TID (from <code>ps</code>).</li><li>VFS regression lines <code>BUG-0178 legal O_RDWR write: FAIL</code>, <code>BUG-0179 case-sensitive ramfs: FAIL</code>, <code>BUG-0180 hole is zeros: FAIL</code>, <code>BUG-0182 mode-0000 refused: FAIL</code>, <code>BUG-0184 umount / refused: FAIL</code> — these mark FIXED bugs; a FAIL here is a regression. Report with the fstest output.</li><li><code> FAIL: kernel PT frame was FREED by user-AS destroy (BUG-0136)</code> — same class (regression marker).</li><li>heap wrap guards: <code>FAIL: wrap size 0xFFFFFFFFFFFFFFF1 was served</code>, <code>FAIL: 64 GiB size was served</code>, <code>FAIL: legitimate 4096 B alloc refused</code> — allocator hardening regression; report.</li><li>i2c: <code>i2cget: error (&lt;code&gt;)</code>, <code>i2cset: error</code>, <code>controller: i801/PIIX4 not present FAIL</code> — controller absent (or the i801 status words: NACK/bus error/transaction failed/timeout).</li></ul><h3 id="_5-9-display" tabindex="-1">5.9 display <a class="header-anchor" href="#_5-9-display" aria-label="Permalink to &quot;5.9 display&quot;">​</a></h3><ul><li><code>chinesetest: FAILURES PRESENT</code> / <code>encoding-test: FAIL</code> / <code>ime_test_fail</code> — the CJK battery failed; report (font blob or codec regression).</li><li>touchtest verdict block: <code>touchtest: FAIL</code> + per-gesture <code>descriptor parse FAIL</code>, <code>TAP gesture FAIL</code>, <code>SCROLL gesture FAIL</code>, <code>PINCH gesture FAIL</code>, <code>SWIPE gesture FAIL</code> — descriptor or gesture-engine issue.</li></ul><h3 id="_5-10-font" tabindex="-1">5.10 font <a class="header-anchor" href="#_5-10-font" aria-label="Permalink to &quot;5.10 font&quot;">​</a></h3><ul><li><code>chinese_font gz layout mismatch - regenerate chinese_font_data.c</code> — build-time guard (also a _Static_assert); regenerate the font data.</li><li>The negative fixtures (<code>zone 95 rejected</code>, <code>wei 0 rejected</code>, <code>surrogate ED A0 80 rejected</code>, ...) — hostile inputs; each rejection is a PASS.</li></ul><h3 id="_5-11-fs" tabindex="-1">5.11 fs <a class="header-anchor" href="#_5-11-fs" aria-label="Permalink to &quot;5.11 fs&quot;">​</a></h3><ul><li>VFS: <code>vfs_init: failed to allocate global root</code>, <code>vfs_mount: invalid path</code>, <code>vfs_mount: unknown fs type</code>, <code>vfs_mount: fs mount failed</code>, <code>vfs: cannot unmount the root filesystem</code>, <code>vfs_mount: parent path does not exist</code>, <code>vfs_mount: mount point exists and is not a directory</code> — mount-argument problems; <code>mounts</code> shows what exists.</li><li><code>ramfs: mount at / failed</code> — fatal at boot (no rootfs); report.</li><li>L1 face: <code>tree: bad path</code>, <code>mount: failed</code>, <code>umount: bad path</code>, <code>umount: cannot unmount the root filesystem</code>, <code>umount: target is busy - close open files first</code>, <code>umount: unmount nested mounts first</code>, <code>umount: failed (not mounted?)</code>, <code>... FAILED - no FAT32 partition on device or drive not present</code> — close open files, unmount children first (<code>mounts</code> shows nesting).</li><li>FAT32: <code>fat32: invalid device string</code>, <code>fat32: read boot sector failed rc=&lt;N&gt;</code>, <code>fat32: invalid BPB</code>, <code>fat32: not a FAT32 volume (FAT12/16 detected)</code>, <code>fat32: ext_flags active FAT out of range</code>, <code>fat32: FAT cache alloc failed</code>, <code>fat32: FAT read failed</code> — the volume is not a mountable FAT32; <code>fatstat</code> shows the parsed BPB.</li><li>exFAT: <code>exfat: invalid number_of_fats</code>, <code>exfat: warning - volume was not cleanly unmounted</code> (dirty flag — mount proceeds), the rest as FAT32.</li><li>ext4 (read-only): <code>ext4: not an ext4 volume (bad magic)</code>, <code>ext4: unsupported INCOMPAT feature bits 0x&lt;hex&gt; - mount refused</code>, <code>ext4: unsupported block size (log_block_size &gt; 6)</code>, <code>ext4: invalid inode size (must be 128..1024, power of two)</code>, <code>ext4: read root inode failed</code> — the volume uses features the RO driver refuses; mount it read-only elsewhere to inspect.</li></ul><h3 id="_5-12-health" tabindex="-1">5.12 health <a class="header-anchor" href="#_5-12-health" aria-label="Permalink to &quot;5.12 health&quot;">​</a></h3><ul><li><code>health: export FAILED</code> / <code>health: export FAILED (no filesystem mounted?)</code> — export needs a writable target; mount a volume.</li><li>Alarms (<code>alarm: memory &gt;90% used</code>, <code>alarm: &lt;n&gt; active tasks (&gt;64)</code>, <code>alarm: CPU &gt;=90% busy for 10 consecutive seconds</code>) — see <a href="./silent-failures.html">silent-failures.md</a> §health-first.</li></ul><h3 id="_5-13-ipc-l1-loader" tabindex="-1">5.13 ipc / l1 / loader <a class="header-anchor" href="#_5-13-ipc-l1-loader" aria-label="Permalink to &quot;5.13 ipc / l1 / loader&quot;">​</a></h3><ul><li><code>unknown program: &lt;name&gt;</code> — <code>run</code>/registry lookup failed. <code>help -a</code> to check spelling.</li><li><code>not a dynamic executable (unknown type)</code> — <code>ldd</code> on a static program; expected.</li><li>Loader negative fixtures (<code>so_unload(0) = -1 (NULL handle rejected) - PASS</code>, <code>elf_get_needed(truncated 48B) = 0 (rejected) - PASS</code>, ...) — hostile-input rejections; correct behavior.</li></ul><h3 id="_5-14-klog" tabindex="-1">5.14 klog <a class="header-anchor" href="#_5-14-klog" aria-label="Permalink to &quot;5.14 klog&quot;">​</a></h3><ul><li><code>logcat: bad level (debug/info/warn/error/fatal or 0-4)</code> / <code>logcat: unknown option &lt;o&gt;</code> — argument guards.</li><li><code>logctl: bad level</code> / <code>usage: logctl enable|disable debug|info|warn|error|fatal</code> — same.</li><li><code>klog: flush FAILED (no filesystem mounted?)</code> / rotate / export variants — need /var/log; mount a volume first.</li><li><code>logctl: bad level (&#39;-&#39; = any)</code> — filter syntax note.</li></ul><h3 id="_5-15-net-—-core" tabindex="-1">5.15 net — core <a class="header-anchor" href="#_5-15-net-—-core" aria-label="Permalink to &quot;5.15 net — core&quot;">​</a></h3><ul><li><code>virtio TX timeout: avail_idx=&lt;N&gt; used_idx=&lt;N&gt; ISR=0x&lt;hex&gt; STATUS=0x&lt;hex&gt; desc_addr=0x&lt;hex&gt;</code> — the one true TX-timeout template; the virtio NIC stopped consuming descriptors. QEMU: restart with <code>-device virtio-net-pci</code>; report if persistent.</li><li><code>[tcp] send fail: sock=&lt;n&gt;</code> — TCP transmit error; check link state (<code>ifconfig</code>).</li><li>DNS family: <code>DNS resolution failed</code>, <code>DNS resolution failed (timeout)</code>, <code>timeout</code>, <code>MX: no mail exchanger (or timeout)</code> and the AAAA/CNAME/NS/SRV/TXT variants — see <a href="./network-issues.html">network-issues.md</a>.</li><li><code>DHCP failed (timeout)</code> — the DISCOVER→OFFER→REQUEST→ACK chain got no answer; see <a href="./network-issues.html">network-issues.md</a>.</li><li><code> UDP rx dropped (buffer full): &lt;n&gt;</code> / <code> IP frag dropped: &lt;n&gt;</code> — socket-buffer/reassembly drop counters; heavy-load symptom.</li><li><code>firewall reset (rules, conntrack, policies)</code> — informational after <code>firewall reset</code>.</li><li><code>rule not found</code> — <code>firewall del &lt;n&gt;</code> with a stale index; <code>firewall</code> re-lists.</li><li>wget: <code>cannot resolve host</code>, <code>out of memory</code>, <code>socket failed</code>, <code>connect failed</code>, <code>TLS failed (code &lt;n&gt;)</code>, <code>no response (timeout)</code>, <code>wget: cannot create file, printing to console:</code> — the body prints to console when the target file cannot be created.</li><li><code>tcptest: alloc failed</code> — OOM.</li></ul><h3 id="_5-16-net-—-ssh-client" tabindex="-1">5.16 net — ssh client <a class="header-anchor" href="#_5-16-net-—-ssh-client" aria-label="Permalink to &quot;5.16 net — ssh client&quot;">​</a></h3><ul><li>Transport: <code>[ssh] net_socket failed</code>, <code>net_connect failed</code>, <code>failed to send version banner</code>, <code>failed to receive server banner</code>, <code>[ssh] server banner too long or unterminated</code> — connectivity/peer problems.</li><li>kex: <code>failed to send KEXINIT</code> / <code>receive KEXINIT</code> / <code>send KEX_ECDH_INIT</code> / <code>receive KEX_ECDH_REPLY</code>, <code>[ssh] x25519 shared secret computation failed</code>, <code>[ssh] x25519 shared secret is all-zero (invalid server key)</code>, <code>[ssh] exchange hash input exceeds 4096B page</code> — broken or hostile peer.</li><li>Host trust: <code>[ssh] TOFU: cannot write /etc/ssh_known_hosts (read-only fs?)</code> (expected on ramfs /etc), <code>[ssh] host signature missing</code>, <code>[ssh] signature length mismatch</code>, <code>[ssh] HOST SIGNATURE INVALID - disconnecting</code>, <code>[ssh] WARNING: HOST KEY CHANGED! (possible MITM)</code>, <code>[ssh] connection refused (delete the entry in /etc/ssh_known_hosts to re-trust)</code> — the TOFU model speaking; delete the entry only if you know why the key changed.</li><li>Auth: <code>[ssh] USERAUTH_FAILURE — public key rejected</code>, <code>[ssh] USERAUTH_FAILURE — wrong password</code>, <code>[ssh] publickey unavailable (no /etc/ssh_client_key), retrying with password</code> — credentials.</li><li>Session: <code>[ssh] failed to send CHANNEL_OPEN</code>, <code>CHANNEL_OPEN failed</code>, <code>[ssh] rekey failed - dropping session</code>, <code>[ssh] timeout reading channel data</code>.</li><li>Integrity: <code>[ssh] MAC verify FAIL on incoming encrypted packet</code>, <code>[ssh] invalid packet_length in encrypted packet</code>, <code>[ssh] unexpected msg type &lt;n&gt;</code> — tampering or version skew; capture serial.</li></ul><h3 id="_5-17-net-—-sshd-server" tabindex="-1">5.17 net — sshd server <a class="header-anchor" href="#_5-17-net-—-sshd-server" aria-label="Permalink to &quot;5.17 net — sshd server&quot;">​</a></h3><ul><li><code>host key file corrupt; regenerating</code> — self-healing first-boot path.</li><li><code>ERROR: cannot obtain a per-installation host key - refusing to start sshd (embedded universal key removed)</code> — no key and keygen impossible (no entropy/memory). Pre-seed <code>etc.img</code> via <code>tools/host_keygen_etc.py</code> (see <a href="./network-issues.html">network-issues.md</a>).</li><li><code>ERROR: cannot spawn the sshd-hkgen thread</code> — thread-table full; <code>ps</code>.</li><li><code>recv_unenc: timeout reading 4-byte length</code>, <code>recv_unenc: bad pkt_len=&lt;n&gt;</code>, <code>recv: bad packet_length=&lt;n&gt;</code>, <code>recv: bad blocking, remaining=&lt;n&gt;</code> — hostile or broken client framing.</li><li><code>MAC verify FAIL on incoming packet</code> — tampering.</li><li><code>publickey signature INVALID</code>, <code>USERAUTH_FAILURE sent (bad credentials)</code>, <code>too many authentication failures</code> / <code>auth failure cap reached - disconnecting</code> — auth path.</li><li><code>second connection during active session - refusing it</code>, <code>too many connections (one session at a time)</code> — one session by design.</li><li><code>listen socket alloc failed</code>, <code>tcp_listen failed</code> — port in use / OOM.</li><li><code>curve25519 shared secret is all-zero (invalid client key)</code>, <code>exchange hash input too large</code> — hostile kex.</li></ul><h3 id="_5-18-net-—-tls-https" tabindex="-1">5.18 net — TLS (HTTPS) <a class="header-anchor" href="#_5-18-net-—-tls-https" aria-label="Permalink to &quot;5.18 net — TLS (HTTPS)&quot;">​</a></h3><ul><li><code>ServerHello recv/parse failed</code>, <code>ServerHello legacy version mismatch</code>, <code>EncryptedExtensions failed</code>, <code>Certificate failed</code>, <code>CertificateVerify recv failed</code>, <code>server Finished verify_data mismatch</code> — handshake step failures; the step name is the diagnosis.</li><li><code>[tls] x509 verify failed: &lt;why&gt;</code> + <code> - connection REFUSED</code> — the trust decision (see X509_E_*). Self-signed chains are REFUSED by default.</li><li><code>record decrypt failed (AEAD open)</code>, <code>transcript overflow (certificate chain too large)</code>, <code>tls12 hs_log overflow (chain too large)</code>, <code>[tls-dbg] PSS verify failed: transcript_len=&lt;n&gt;</code> — peer crypto broken/hostile.</li></ul><h3 id="_5-19-net-—-wireless-bt" tabindex="-1">5.19 net — wireless + BT <a class="header-anchor" href="#_5-19-net-—-wireless-bt" aria-label="Permalink to &quot;5.19 net — wireless + BT&quot;">​</a></h3><ul><li><code>WEP (not supported)</code>, <code>WPA2 (not supported)</code>, <code>WPA1 (not supported)</code> — the honest state machine: association with these securities is refused.</li><li><code>associate failed (honest state machine result)</code>, <code>connection failed (honest HCI result)</code> — hardware/driver reality reported as-is.</li><li>Driver-sim fixtures (<code>ath9k non-atheros rejected</code>, <code>iwl ucode bad magic honest</code>, ...) — correct rejections.</li></ul><h3 id="_5-20-ocembed-the-ocire-embed-channel" tabindex="-1">5.20 ocembed (the OCIRE embed channel) <a class="header-anchor" href="#_5-20-ocembed-the-ocire-embed-channel" aria-label="Permalink to &quot;5.20 ocembed (the OCIRE embed channel)&quot;">​</a></h3><ul><li><code>mailbox magic mismatch at lba=%u - no signal written</code> / <code>log ring magic mismatch at lba=%u - append refused</code> — the target block is not a valid mailbox (OCIREMB2/OCIRELOG1).</li><li><code>L1SVC ocire op=%u refused: caller is not ocire_guard</code> + <code>ocire: refused (guard-only channel)</code> — only the OCIRE log agent may call cat-18 ops 4/5; expected for anyone else.</li><li><code>no block device covers the mailbox lba=%u</code> / <code>SIGNAL_OK write failed</code> — no recovery volume; embed inactive (normal on plain installs).</li><li><code>ocire embed: boot signal FAILED - see log</code> / <code>ocire: append FAILED (ring io)</code> — embed channel broken; OCIRE supervision degrades to unsupervised.</li><li><code>ocire embed: whole-disk write protection ARMED (&lt;range&gt; bytes, protected)</code> — informational: writes to the recovery disk are closed.</li><li><code>i6300esb disarm: device absent</code> — OCIRE/OCSE boot: no TCO to disarm; harmless.</li><li><code>ocire embed: agent spawn FAILED - the recovery log channel stays unused</code> — process table full or image missing.</li></ul><h3 id="_5-21-power" tabindex="-1">5.21 power <a class="header-anchor" href="#_5-21-power" aria-label="Permalink to &quot;5.21 power&quot;">​</a></h3><ul><li><code>System halted.</code> — normal <code>halt</code>.</li><li><code>S3 resume failed.</code> — suspend/resume path broken on this machine.</li><li><code>Power off not supported. System halted.</code> — all ports exhausted (OC_POWER_E_UNSUPPORTED); use host power.</li><li><code>Suspend not supported (ACPI required).</code> — no ACPI on this machine.</li><li><code>sleep: invalid time</code> — <code>sleep</code> needs a positive number (fractional ok).</li><li><code>poweroff_test: no power-off port took effect on this machine - power-off NOT observed : FAIL</code> — the probe&#39;s honest verdict in a VM.</li></ul><h3 id="_5-22-selfhost-update-config-autoupdate" tabindex="-1">5.22 selfhost (update + config + autoupdate) <a class="header-anchor" href="#_5-22-selfhost-update-config-autoupdate" aria-label="Permalink to &quot;5.22 selfhost (update + config + autoupdate)&quot;">​</a></h3><ul><li><code>update: download failed: &lt;why&gt;</code> / <code>download size mismatch</code> / <code>update: cannot determine target slot (not booted from A/B?)</code> / <code>update: install failed: &lt;why&gt;</code> / <code>update: setting boot failed</code> / <code>update: check failed: &lt;why&gt;</code> / <code>rollback: failed</code> — the <code>&lt;why&gt;</code> is the OC_UPDATE_E_* text; see <a href="./error-codes.html">error-codes.md</a> and <a href="./silent-failures.html">silent-failures.md</a> §OTA-chain.</li><li><code>abupdate: boot slot B (bootfail marker written)</code> — deliberate failover marker; the next boot rolls back to A.</li><li>config: <code>config: cannot read /etc/opencube.conf</code>, <code>: config file missing</code>, <code>: key not found</code>, <code>: read error</code>, <code>config: write rejected (empty, non-ASCII, too long, or invalid value)</code>, <code>config: restore failed</code> — the value guards are strict by design; <code>config list</code> for valid keys.</li><li>autoupdate: <code>[autoupdate] skipped: network not ready</code>, <code>[autoupdate] check failed (code &lt;n&gt;)</code> — silent by design; see <a href="./silent-failures.html">silent-failures.md</a>.</li></ul><h3 id="_5-23-sysapi" tabindex="-1">5.23 sysapi <a class="header-anchor" href="#_5-23-sysapi" aria-label="Permalink to &quot;5.23 sysapi&quot;">​</a></h3><ul><li>klog WARN <code>kill pid=%d refused: ocire_guard process</code> — the OCIRE log agent is unkillable by design; ring 3 only sees &quot;no such process&quot; (open boundary).</li></ul><h3 id="_5-24-time" tabindex="-1">5.24 time <a class="header-anchor" href="#_5-24-time" aria-label="Permalink to &quot;5.24 time&quot;">​</a></h3><ul><li><code>rtc pie: invalid rate/count (rate 3..15, count 1..100000)</code>, <code>alarm test: internal error</code>, <code>counter test: FAIL (non-monotonic)</code>, <code>tsc cal: FAIL (drift &gt; 10%)</code>, <code>tsc delay: FAILED (no calibration available)</code> — calibration failures; run <code>tsc</code>/<code>hpet</code>/<code>pmtimer</code> status.</li><li>The honest family: <code>hpet: legacy route not available (honest skip)</code>, <code>oneshot: arm failed (honest FAIL)</code>, <code>calibration: FAILED (no samples)</code> — absent hardware reported honestly, not a bug.</li></ul><h3 id="_5-25-tui" tabindex="-1">5.25 tui <a class="header-anchor" href="#_5-25-tui" aria-label="Permalink to &quot;5.25 tui&quot;">​</a></h3><ul><li>Desktop: <code>page error</code>, <code>page &#39;%s&#39; failed (rc=%d)</code>, <code>tui: registry alloc failed</code>, <code>tui: desktop init failed</code>, <code>tui: desktop window failed</code>, <code>out of memory</code>, <code>command failed</code> — desktop internals; report with <code>dmesg</code>.</li><li>Editor: <code>open %s failed (rc=%d)</code>, <code>%s: partial load, save refused</code>, <code>partial buffer: saving refused</code>, <code> [PARTIAL: save refused]</code> — the 256-line × 128-byte limits; the refusal protects your file.</li><li>Files: <code>stat %s failed</code>, <code>open %s failed</code>, <code>unknown fs type: %s (ramfs/fat32/exfat/ext4)</code>.</li><li>Sysinfo/update: <code>check failed</code>, <code>manifest has no package fields (download refused)</code>, <code>download failed (rc=%d)</code>, <code>verify failed (rc=%d) - package discarded</code>, <code>install failed (rc=%d)</code>, <code>installed but set-boot failed (rc=%d)</code>, <code>rollback failed</code> — the TUI mirrors of the OC_UPDATE codes.</li><li>Time page: <code>value out of range (1980-2099, valid M/D/H/M/S)</code>, <code>RTC write failed (SET-window readback mismatch)</code>.</li><li>Security strings <code>WEP/WPA1/WPA2 (not supported)</code> — honest.</li><li>Extension self-tests: <code>menu: FAIL (</code>, <code>page: FAIL</code>, <code>widget: FAIL</code>, <code>cmd: FAIL</code>, <code>theme: FAIL</code>, <code>key: FAIL</code>, <code>event: FAIL</code>, <code>selftest FAILED (see log)</code> — run <code>tui-test</code>, then <code>dmesg</code>.</li></ul><h3 id="_5-26-usb" tabindex="-1">5.26 usb <a class="header-anchor" href="#_5-26-usb" aria-label="Permalink to &quot;5.26 usb&quot;">​</a></h3><ul><li><code>blk_read_sectors failed</code>, <code>too few</code>, <code>data mismatch</code>, <code>short write / error</code> — USB MSC read/write test failures; try <code>usb_storage_test</code> with the stick replugged.</li></ul><h3 id="_5-27-watchdog" tabindex="-1">5.27 watchdog <a class="header-anchor" href="#_5-27-watchdog" aria-label="Permalink to &quot;5.27 watchdog&quot;">​</a></h3><ul><li><code>watchdog: task create FAILED</code> — the <code>test</code> injector could not spawn; process table full.</li><li><code>watchdog hw: start FAILED (bad timeout?)</code> / <code>stop FAILED</code> / <code>feed FAILED (not armed?)</code> / <code>set FAILED</code> — hw API guards; check <code>watchdog hw status</code> first.</li><li><code>watchdog: register FAILED (table full?)</code> — 8 slots max; <code>watchdog slots</code> to inspect.</li><li><code>watchdog: bad slot id</code> — <code>feed &lt;id&gt;</code> with a dead id.</li><li>Usage lines echo the exact ranges (<code>hw timeout &lt;2..63 seconds&gt;</code>, <code>timeout &lt;id&gt; &lt;ms 100..3600000&gt;</code>).</li></ul><h2 id="_6-ocos-drivers-6-classes" tabindex="-1">6. OCOS drivers (6 classes) <a class="header-anchor" href="#_6-ocos-drivers-6-classes" aria-label="Permalink to &quot;6. OCOS drivers (6 classes)&quot;">​</a></h2><h3 id="_6-1-audio-drivers" tabindex="-1">6.1 audio drivers <a class="header-anchor" href="#_6-1-audio-drivers" aria-label="Permalink to &quot;6.1 audio drivers&quot;">​</a></h3><ul><li><code>es1370: block IRQ timeout</code> / <code>es1370: IRQ registration failed - device disabled</code> — the blocking wait missed the IRQ / IRQ line lost.</li><li><code>sb16: block IRQ timeout</code> / <code>sb16: IRQ 5 registration failed - device disabled</code> — same template on IRQ 5.</li><li><code>hda: verb timeout verb=0x&lt;hex&gt;</code> / <code>hda: controller reset failed</code> / <code>hda: codec enumeration failed</code> — HDA verb channel broken; QEMU <code>-device intel-hda</code> or real-hardware BIOS settings.</li><li><code>virtio-snd: control timeout</code>, <code>required PCI capabilities not found</code>, <code>not enough virtqueues</code>, <code>queue setup failed</code> — virtio-snd setup; check <code>-device virtio-sound-pci</code>.</li></ul><h3 id="_6-2-bus-acpi-aml-smbus" tabindex="-1">6.2 bus (ACPI / AML / SMBus) <a class="header-anchor" href="#_6-2-bus-acpi-aml-smbus" aria-label="Permalink to &quot;6.2 bus (ACPI / AML / SMBus)&quot;">​</a></h3><ul><li><code>ACPI: table with bad length skipped</code> / <code>ACPI: table checksum mismatch skipped</code> / <code>ACPI: no valid RSDP found</code> / <code>ACPI: RSDT/XSDT invalid</code> — firmware tables; the system degrades (no ACPI power paths).</li><li>AML interpreter guards (hostile-DSDT protection): <code>AML: unsupported op 0x&lt;hex&gt;</code>, <code>node pool allocation failed</code>, <code>op budget exceeded</code>, <code>while-loop guard tripped</code>, <code>table length out of range</code> — the interpreter refuses to hang on a bad DSDT. Firmware issue.</li><li>i801 SMBus: <code>NACK/device error</code>, <code>bus error/collision</code>, <code>transaction failed</code>, <code>timeout</code>, <code>10-bit not supported by i801-class SMBus</code>, <code>bad address</code>, <code>unsupported combined transfer</code> — status decode; mostly device-side.</li></ul><h3 id="_6-3-misc-bt-hci-mjpeg" tabindex="-1">6.3 misc (BT HCI / MJPEG) <a class="header-anchor" href="#_6-3-misc-bt-hci-mjpeg" aria-label="Permalink to &quot;6.3 misc (BT HCI / MJPEG)&quot;">​</a></h3><ul><li>HCI status names <code>unknown-cmd</code>, <code>unknown-conn</code>, <code>hw-fail</code>, <code>timeout</code> — controller replies.</li><li>MJPEG decoder rejects (25 guards: <code>missing SOI</code>, <code>bad segment length</code>, <code>progressive JPEG not supported (baseline only)</code>, <code>lossless/arithmetic JPEG not supported</code>, ...) — kernel log only; the UVC layer reports capture failure upstream.</li></ul><h3 id="_6-4-net-drivers-—-the-merged-init-failed-template" tabindex="-1">6.4 net drivers — the merged <code>init failed</code> template <a class="header-anchor" href="#_6-4-net-drivers-—-the-merged-init-failed-template" aria-label="Permalink to &quot;6.4 net drivers — the merged `init failed` template&quot;">​</a></h3><p>Each NIC driver prints <code>&lt;name&gt;: init failed</code> when its probe fails:</p><p><code>e1000e: init failed</code>, <code>igb: init failed</code>, <code>ixgbe: init failed</code>, <code>rtl8139: init failed</code>, <code>rtl8169: init failed</code> (rtl8168 face), <code>bcm57xx: init failed</code>.</p><p>One unified triage (see <a href="./network-issues.html">network-issues.md</a>): <code>lspci</code> (is the card on the bus?) → <code>pcidump &lt;b:d.f&gt;</code> (BARs sane?) → the family status command (<code>e1000e</code>, ...) → the family selftest. Extra: <code>bcm57xx: DMA memory above 4GiB - refused</code> — the NIC cannot reach its DMA buffer; a memory-layout issue on that machine.</p><h3 id="_6-5-storage-drivers" tabindex="-1">6.5 storage drivers <a class="header-anchor" href="#_6-5-storage-drivers" aria-label="Permalink to &quot;6.5 storage drivers&quot;">​</a></h3><ul><li>AHCI: <code>ahci: issue fail (PxIS.TFE) IS=0x&lt;hex&gt;</code>, <code>ahci: issue fail (PxTFD.ERR) TFD=0x&lt;hex&gt;</code>, <code>ahci: issue TIMEOUT CI=0x&lt;hex&gt;</code>, <code>&lt;port&gt;: ATAPI (not supported)</code>, <code>&lt;port&gt;: failed to stop engine</code>, <code>&lt;port&gt;: out of memory</code>, <code>&lt;port&gt;: IDENTIFY failed</code>, <code>ahci: BAR5 invalid</code>, <code>&lt;dev&gt;) - controller skipped</code>.</li><li>ATA: <code>ata: PIO read DRQ timeout lba=&lt;n&gt;</code>; <code>atadma: xfer FAIL rc=&lt;n&gt;</code>; <code>ata_dma: init re-entered with live controllers - refusing, ...</code> (double-init guard).</li><li>NVMe: <code>nvme: BAR0 invalid</code>, <code>nvme: disable timeout, rewriting CC=0 and retrying</code>, <code>nvme: ready timeout, resetting and retrying</code>, <code>nvme: out of memory (admin queue|io queue|bounce)</code>, <code>nvme: Identify Controller failed</code>, <code>nvme: Identify Namespace failed</code>, <code>nvme: unsupported formatted LBA size (only 512B supported; got &lt;n&gt;)</code>, <code>nvme: Create I/O CQ/SQ failed</code>.</li><li>virtio-blk: <code>virtio-blk: no legacy PCI device found (modern-only devices not supported)</code>, <code>virtio-blk: BAR0 invalid</code>, <code>invalid queue size</code>, <code>out of memory</code>, <code>WARNING: capacity read failed (legacy config not available?)</code>, <code>used-ring poll timeout</code>, <code>virtio-blk: write rejected (device is read-only)</code> — the last one is the QEMU <code>-drive file=...,readonly=on</code> semantic, not a bug.</li></ul><h3 id="_6-6-usb-host-class-drivers" tabindex="-1">6.6 USB host + class drivers <a class="header-anchor" href="#_6-6-usb-host-class-drivers" aria-label="Permalink to &quot;6.6 USB host + class drivers&quot;">​</a></h3><ul><li>Enumeration: <code>usb: GET_DESCRIPTOR(8) failed</code>, <code>SET_ADDRESS failed</code>, <code>GET_DESCRIPTOR(18/config9/config) failed</code>, <code>SET_CONFIGURATION failed</code>, <code>hub GET_DESCRIPTOR failed</code> — the device did not enumerate; replug, check the hub.</li><li>DMA reachability (by design on &gt;4 GiB machines): <code>usb: UHCI probe failed - driver state above 4GiB, 32-bit DMA</code>, <code>UHCI probe failed - no 32-bit-reachable frame-list page</code> (and schedule/ISO/bounce variants), <code>usb: EHCI probe failed - driver state above 4GiB, 32-bit DMA</code>, <code>EHCI probe failed - DMA frame at/above 4GiB</code>, <code>usb: OHCI probe failed - pool incomplete or above 4GiB (32-bit DMA HC)</code>.</li><li>xHCI: <code>xhci: ENABLE_SLOT failed</code>, <code>ADDRESS_DEVICE(BSR) failed</code>, <code>xhci: port reset fail ccs=0 w=0x&lt;hex&gt;</code>, <code>controller reset timeout</code>, <code>scratchpad page alloc failed</code>, <code>probe failed, allocated frames released</code>.</li><li>EHCI: <code>ehci: port reset fail ccs=0 w=0x&lt;hex&gt;</code>.</li><li>OHCI: <code>ohci: reset timeout</code>.</li><li>MSC: <code>msc: CBW bulk out failed</code>, <code>msc: data phase failed</code>, <code>msc: CSW bulk in failed rc=&lt;n&gt;</code>, <code>msc: CSW bad signature or tag</code>, <code>usb-msc: device not ready</code>, <code>usb-msc: inquiry failed</code>, <code>usb-msc: read capacity failed</code>, <code> NOT registered (blk layer rejected block size &lt;n&gt;)</code>.</li><li>Audio class: <code>usbaudio: SET_INTERFACE failed</code>, <code>device rejected SET_CUR(SAM_FREQ)</code>, <code>SET_CUR(MUTE) rejected</code>, <code>SET_CUR(VOLUME) rejected</code>.</li><li>Serial: <code>usb-serial: configure failed</code>.</li></ul><h2 id="_7-l1apps-5-classes" tabindex="-1">7. l1apps (5 classes) <a class="header-anchor" href="#_7-l1apps-5-classes" aria-label="Permalink to &quot;7. l1apps (5 classes)&quot;">​</a></h2><h3 id="_7-1-the-shared-i18n-templates-250-apps" tabindex="-1">7.1 The shared i18n templates (250 apps) <a class="header-anchor" href="#_7-1-the-shared-i18n-templates-250-apps" aria-label="Permalink to &quot;7.1 The shared i18n templates (250 apps)&quot;">​</a></h3><ul><li><code>&lt;app&gt;: service call failed (rc=-1)</code> (i18n key <code>svc_call_failed</code>) — the L1SVC bridge returned -1. <strong>Unified triage</strong>: (1) re-run — transient? (2) <code>health</code> + <code>dmesg 100</code> (the service&#39;s klog line tells the real story); (3) run the family&#39;s <code>_test</code> stub; (4) if the service itself reports healthy, it is an op-argument problem — check the command&#39;s grammar in <a href="./../manual/function-dictionary.html">../manual/function-dictionary.md</a>.</li><li><code>service call failed</code> (wizard variant, <code>wiz_svc_failed</code>) — the mega wizard&#39;s copy; same triage.</li><li><code>[save failed]</code> / <code>[save failed - stay in editor]</code> — editor save failure; usually a read-only filesystem.</li></ul><h3 id="_7-2-classic-per-app-errors" tabindex="-1">7.2 Classic per-app errors <a class="header-anchor" href="#_7-2-classic-per-app-errors" aria-label="Permalink to &quot;7.2 Classic per-app errors&quot;">​</a></h3><ul><li><code>cat: cannot open </code> (same template: head/tail/sort/uniq/wc/awk) — <code>ls</code> the path.</li><li><code>cp: cannot open &#39;&lt;src|dst&gt;&#39;</code> / <code>mv: ...</code> — same.</li><li><code>rm: cannot remove &#39;&lt;path&gt;&#39;</code> / <code>rmdir: cannot remove &#39;&lt;path&gt;&#39;</code> — file busy or not empty.</li><li><code>mkdir: cannot create &#39;&lt;path&gt;&#39;</code> — exists or no parent.</li><li><code>ln: cannot create symlink (target must be an absolute path)</code> / <code>ln: hard link failed (rc=&lt;n&gt;)</code> — the symlink rule is absolute-only.</li><li><code>chmod: cannot change mode</code> / <code>chown: cannot change owner</code> / <code>stat: cannot stat &#39;&lt;path&gt;&#39;</code>.</li><li><code>write: cannot open </code> / <code>write: write failed on </code>.</li><li><code>awk: missing {print ...}</code> — the tiny awk only supports <code>{print ...}</code>.</li><li><code>sed: unknown script</code> — only <code>s///</code>, <code>-n Np</code>, <code>Nd</code> exist.</li><li><code>date: ms since boot (no RTC driver)</code> — fallback notice (VMs).</li><li><code>free: SYS_MEMINFO unavailable (kernel too old)</code> / <code>ps: SYS_PS unavailable (kernel too old)</code> — version skew.</li><li><code>run: fork failed</code> / <code>run: unknown program: &lt;name&gt;</code>.</li><li><code>help: unknown option &#39;&lt;o&gt;&#39;</code> / <code>(registry listing failed)</code>.</li><li>ush: <code>ush: &#39;exit&#39; is not available; use &#39;shutdown&#39; to power off, &#39;reboot&#39; to restart</code>, <code>ush: syntax error near &#39;&gt;&#39;</code> / <code>near &#39;&lt;&#39;</code>, <code>ush: alias expansion too long</code>, <code>ush: fork failed</code>, <code>ush: command not found: &lt;cmd&gt;</code>.</li></ul><h3 id="_7-3-mega-app-dispatch-errors" tabindex="-1">7.3 Mega-app dispatch errors <a class="header-anchor" href="#_7-3-mega-app-dispatch-errors" aria-label="Permalink to &quot;7.3 Mega-app dispatch errors&quot;">​</a></h3><ul><li><code>disk-tool: unknown op: &lt;op&gt;</code> (and the files/net-tool/sound-tool/ sysdiag/hwinfo/power variants), <code>files: unknown program: &lt;p&gt;</code> — the verbatim table miss; <code>help -w</code> lists what exists.</li><li>update wizard states (i18n keys <code>net_probe_failed</code>, <code>ab_probe_failed</code>, <code>ab_missing</code>, <code>ab_mismatch</code>, <code>ab_warn</code>, <code>dns_fail</code>, <code>check_unknown</code>, <code>install_skipped</code>, <code>install_failed</code>, <code>reboot_skipped</code>) — each maps to a wizard step outcome; the printed text names the failing step.</li><li><code>WARNING: this destroys all data on that device.</code> (disk-tool <code>dt_warn</code>) — the retype-guard path.</li></ul><h3 id="_7-4-ld-so-the-ring-3-dynamic-loader" tabindex="-1">7.4 ld_so (the ring-3 dynamic loader) <a class="header-anchor" href="#_7-4-ld-so-the-ring-3-dynamic-loader" aria-label="Permalink to &quot;7.4 ld_so (the ring-3 dynamic loader)&quot;">​</a></h3><ul><li><code>&#39;: invalid ELF (magic/ELF64/ET_DYN/phdr bounds)</code>, <code>ld.so: bad main base 0x&lt;hex&gt;</code>, <code>ld.so: bad libfoo.so base 0x&lt;hex&gt;</code> — load failures.</li><li><code>ld.so: symbol reloc with bad index in &#39;&lt;so&gt;&#39;</code>, <code>ld.so: COPY reloc with bad index in &#39;&lt;so&gt;&#39;</code>, <code>ld.so: unknown reloc type &lt;n&gt;</code>.</li><li><code>ld.so: mprotect W^X failed for &#39;&lt;seg&gt;&#39;</code> — W^X enforcement failed.</li><li><code>ld.so: bad DT_NEEDED name in &#39;&lt;so&gt;&#39;</code>, <code>ld.so: cannot load &#39;&lt;lib&gt;&#39;</code>, <code>ld.so: libfoo.so missing DT_SYMTAB or DT_STRTAB</code>, <code>ld.so: failed to relocate libfoo.so</code> / <code>main program</code> — dynamic-chain damage; re-run <code>l1test</code>, <code>so_test</code>, <code>dlsym_test</code>.</li></ul><h3 id="_7-5-test-apps" tabindex="-1">7.5 Test apps <a class="header-anchor" href="#_7-5-test-apps" aria-label="Permalink to &quot;7.5 Test apps&quot;">​</a></h3><ul><li>p2test: <code>UTF8-FAIL short write</code>, <code>READ0-FAIL</code>, <code>PIPE-FAIL round=&lt;n&gt;</code> (+ <code>pipe()=-1 (slot table exhausted?)</code>) — live-fix probes; a FAIL is a real regression of the fix they guard.</li><li>help gates (<code>help_a_test</code> etc.): FAIL = the registry listing shape changed — build or i18n damage.</li><li>g6_oom / stackovf / pf_test / sigsegv_test / int3_user / badapp — deliberate crashers; their &quot;failure&quot; output is the kernel&#39;s containment notices (§kernel).</li></ul><hr><h2 id="_8-known-bugs-—-known-issues-md-github-issues-is-the-live-tracker" tabindex="-1">8. Known bugs — KNOWN_ISSUES.md (GitHub Issues is the live tracker) <a class="header-anchor" href="#_8-known-bugs-—-known-issues-md-github-issues-is-the-live-tracker" aria-label="Permalink to &quot;8. Known bugs — KNOWN_ISSUES.md (GitHub Issues is the live tracker)&quot;">​</a></h2><h3 id="p0" tabindex="-1">P0 <a class="header-anchor" href="#p0" aria-label="Permalink to &quot;P0&quot;">​</a></h3><ul><li><strong>BUG-AUD-2a-001</strong> (kernel/syscall security) — ring 3 can reach kernel memory through standard read/write syscalls (details withheld by security policy). Until fixed: treat every ring-3 program as potentially privileged; do not run untrusted binaries.</li></ul><h3 id="p1-symptom-→-cause-→-what-to-do" tabindex="-1">P1 (symptom → cause → what to do) <a class="header-anchor" href="#p1-symptom-→-cause-→-what-to-do" aria-label="Permalink to &quot;P1 (symptom → cause → what to do)&quot;">​</a></h3><ol><li><strong>BUG-3</strong> OCIRE — interrupts permanently disabled after one <code>core_sched_task_states</code> call (flags-restore idiom). Symptom: recovery kernel goes dead after a scheduler call. Fixed in tree; report if an old build reproduces.</li><li><strong>BUG-4</strong> kernel-stack guard page unmap is a no-op on 2 MiB huge pages (+ stale global TLB). Symptom: the klog WARN <code>kthread %s: guard page unmap FAILED</code> and weaker stack-overflow protection. Known; tracked.</li><li><strong>BUG-5</strong> ush kill race — victim AS destroyed before EXITED mark; a timer tick can schedule the victim on a freed CR3. Symptom: rare crash right after <code>kill</code>. Fixed; <code>wp01_killrace_test.py</code> guards it.</li><li><strong>BUG-6</strong> exec-failure/OOM paths leak the whole address space (<code>user_process_create</code>). Symptom: memory slowly vanishes on failed execs. <code>mem</code>; reboot clears.</li><li><strong>BUG-7</strong> <code>sys_execve</code> destroys the old AS before the new one is built; exec cannot fail gracefully. Symptom: exec failure kills the process hard. Known.</li><li><strong>BUG-20</strong> ACPI AML OpRegion access has no bounds checks — a malicious DSDT gets arbitrary physical R/W. Do not boot untrusted firmware tables.</li><li><strong>BUG-21</strong> TLS cert-chain verification failure only warned and continued. <strong>Now REFUSED by default</strong> (the HTTPS E2E item 0); the explicit opt-in is <code>config set tls.insecure 1</code>.</li><li><strong>BUG-22</strong> DNS transaction ID hardcoded 0x1234, responses unvalidated — offline poisoning possible. Symptom: bizarre resolutions on hostile LANs. Known.</li><li><strong>BUG-24</strong> TCP RTO retransmit in IRQ-off timer context can busy-wait in ARP; an expired ARP entry deadlocks the machine. Symptom: hard freeze under packet loss. <code>tcpstats</code> before/after.</li><li><strong>BUG-31</strong> ush command-not-found path unbounded concat into <code>path[64]</code> (stack smashing). Fixed; type garbage commands only on current builds.</li><li><strong>BUG-32</strong> Tab completion unbounded append into <code>line[512]</code>. Fixed (bounded appends).</li><li><strong>BUG-33</strong> alias expansion unbounded strcat into <code>newcmd[512]</code>. Fixed.</li><li><strong>BUG-34</strong> editor: open an over-limit file then save = silent destruction. <strong>Now save REFUSES</strong> (<code>[PARTIAL: save refused]</code>). Never force-save a partial buffer.</li><li><strong>BUG-35</strong> the <code>write</code> app opened RDONLY then wrote; failure ignored (silent no-op). Symptom: <code>write &lt;file&gt;</code> produced nothing. Fixed in 3.0.0.</li><li><strong>BUG-36</strong> <code>cp x x</code> truncates, <code>mv x x</code> deletes (no same-file guard). <strong>Still live</strong>: never cp/mv a file onto itself.</li><li><strong>BUG-46</strong> OCBL ELF loader bounds checks bypassable via integer wraparound. Fixed (overflow-safe math).</li><li><strong>BUG-47</strong> OCIRE supervisor mailbox-write failure formed an infinite reboot loop. Fixed (the anti-reset-loop guard you see as <code>skipping the reboot to avoid a reset loop</code>).</li><li><strong>BUG-63</strong> release chain: boot gate used a staleable /tmp file + <code>|| true</code> swallowed QEMU failure. CI-level false green.</li><li><strong>BUG-64</strong> deep-regression gate assertion structurally always-true. CI-level.</li><li><strong>BUG-65</strong> E2E scripts did not propagate failure exit codes. CI-level.</li><li><strong>BUG-66</strong> screen content never machine-asserted. CI-level.</li><li><strong>BUG-90</strong> docs version/status claims stale in README and friends.</li><li><strong>BUG-91</strong> website stuck at an old build (site-data.js).</li><li><strong>BUG-92</strong> OCIRE banner claimed the wrong version. Fixed (<code>ocire_version_gen.h</code>).</li><li><strong>BUG-99</strong> website ↔ gh-pages out of sync.</li><li><strong>BUG-102</strong> README documented the wrong build command.</li><li><strong>BUG-104</strong> README release-note SHA256 claim not implemented.</li><li><strong>BUG-107</strong> published ISO local copy size/SHA mismatch.</li><li><strong>BUG-109</strong> whole-machine silent freeze race — typing &#39;a&#39;/&#39;u&#39; rapidly or running <code>loop</code> can freeze the system with NO panic and NO watchdog takeover. <strong>The nastiest live P1</strong>: if it reproduces, capture <code>-serial file:</code> and report; the workaround is simply not racing the console input.</li><li><strong>BUG-110</strong> L1 app stdout Chinese renders as tofu on screen (serial fine) — the console fallback lacked the UTF-8 fix (BUG-130 is the root cause).</li><li><strong>BUG-111</strong> nano/vi exit does not clear the screen (afterimages overlap the prompt). Cosmetic; <code>clear</code> after exiting.</li><li><strong>BUG-112</strong> busy-wait <code>loop</code>: 35 s+ with no preemption, no health alarm, no watchdog kill — the declared containment chain fails live. Symptom: the machine feels dead while <code>loop</code> runs. <code>kill</code> from another path or wait it out; tracked.</li><li><strong>BUG-113</strong> OCSE GUI mouse clicks all ineffective (hover renders, clicks don&#39;t trigger). Use the CLI (Ctrl+Alt+F2) or <code>click &lt;x&gt; &lt;y&gt;</code> command.</li><li><strong>BUG-129</strong> OCSE installer↔kernel config dialect split (wizard writes dead keys <code>lang/hostname/boot.slot</code>; kernel reads <code>shell.lang/sys.hostname</code>). Symptom: installer settings ignored at first boot; the kernel rewrites the config. Set keys again from the running system (<code>config set shell.lang zh</code>).</li><li><strong>BUG-130</strong> ush <code>sys_write2</code> console fallback lacked the UTF-8 fix — all ush output tofu on screen (root cause of BUG-110). Fixed with the WP06g1 fix.</li></ol><p>(Lower-priority findings are tracked on GitHub Issues.)</p><h2 id="_9-known-issues-postmortems-19-fixed-3-open-boundaries" tabindex="-1">9. KNOWN_ISSUES postmortems (19 fixed) + 3 open boundaries <a class="header-anchor" href="#_9-known-issues-postmortems-19-fixed-3-open-boundaries" aria-label="Permalink to &quot;9. KNOWN_ISSUES postmortems (19 fixed) + 3 open boundaries&quot;">​</a></h2><h3 id="_2-0-0-postcheck-—-all-fixed-in-2-1-0-17" tabindex="-1">2.0.0 postcheck — all fixed in 2.1.0 (17) <a class="header-anchor" href="#_2-0-0-postcheck-—-all-fixed-in-2-1-0-17" aria-label="Permalink to &quot;2.0.0 postcheck — all fixed in 2.1.0 (17)&quot;">​</a></h3><p>P-01 the tree did not compile on CI (imm8 port constraint ≥ 0x100; GRUB efi_uga module; C23 <code>bool</code> collisions) → port I/O via <code>%dx</code>, module filtering, C23-aware types. P-02/P-03 release-note arithmetic + 231/233 command mapping rows (a regex dropped 2) → ledger regenerated. P-04/P-05 interface truth tables + deletion register. P-06/P-07 docs rewritten to v2 reality. P-08 per-app L1 test matrix added. P-09 Makefile comment. P-10..P-16 website data/assets/evidence/count calipers/governance. P-17 false-positive text defect recorded honestly.</p><h3 id="_2-1-0-open-—-all-fixed-in-2-2-0-2" tabindex="-1">2.1.0 open — all fixed in 2.2.0 (2) <a class="header-anchor" href="#_2-1-0-open-—-all-fixed-in-2-2-0-2" aria-label="Permalink to &quot;2.1.0 open — all fixed in 2.2.0 (2)&quot;">​</a></h3><p>O-01 wp10_tui #DF after a checkupdate round: the deepest call chain (SYS_L1SVC→ota→https→tls→x509→rsa→bn mont, ~23.6 KB) + IRQ nesting exceeded the 20 KiB kthread stack → <code>OC_KTHREAD_STACK_PAGES 6→10</code> (40 KiB window); the corrupted #DF banner (&quot;andled&quot;) also fixed. If you ever see a garbled panic banner, suspect stack pressure. O-02 wait4-vs-fork flaky race — actually deterministic (dead parent&#39;s tid reused, stale zombie exit code collected early) → orphan-detach + fork corpse paths detach; 20/20 clean boots verified.</p><h3 id="open-boundaries-at-3-0-0-wp03-3-by-design" tabindex="-1">Open boundaries at 3.0.0-WP03 (3, by design) <a class="header-anchor" href="#open-boundaries-at-3-0-0-wp03-3-by-design" aria-label="Permalink to &quot;Open boundaries at 3.0.0-WP03 (3, by design)&quot;">​</a></h3><ol><li>ush <code>kill</code> of the ocire_guard process reports generic &quot;no such process&quot;; the real reason is only in klog WARN (<code>kill refused: ocire_guard process</code>). Use <code>dmesg</code> when a kill &quot;mysteriously&quot; fails.</li><li>A bare <code>sti;hlt</code> park remains in 4 proven paths (sys_read keyboard wait, wp8cd fg wait, sdhci timed wait, OTA settle loop) — a hard-freeze risk class if interrupts are lost; documented, not yet restructured.</li><li>The direct-boot GRUB entry carries no oc.* facts — unsupervised by definition (boot through OCBL for the full state machine).</li></ol><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./error-codes.html">error-codes.md</a> — the 61 numeric codes, the 11 panic sites, log formats</li><li><a href="./silent-failures.html">silent-failures.md</a> — failures with no message</li><li><a href="./boot-failures.html">boot-failures.md</a> / <a href="./network-issues.html">network-issues.md</a> / <a href="./storage-issues.html">storage-issues.md</a> — per-domain deep dives</li><li><a href="./common-errors.html">common-errors.md</a> — the short list you reach for first</li></ul>',155)])])}const f=o(c,[["render",i]]);export{m as __pageData,f as default};
